window.ox.install(({action})=>{
const clean=s=>(s||'').replace(/\s+/g,' ').trim();
function challenge(){if(/just a moment|verify you are human|access denied/i.test(document.title)||document.querySelector('#challenge-running'))throw new Error('Human verification required. Show this action page and wait for user completion.');}
async function ready(){const end=Date.now()+12000;while(Date.now()<end){challenge();if(location.pathname==='/engineering'&&document.querySelector('[data-listing-row] h3 a'))return;await new Promise(r=>setTimeout(r,150));}throw new Error('Engineering listing incomplete: expected article rows on /engineering.');}
action('listPosts',{async invoke(args){await ready();let complete=false;for(let i=0;i<10;i++){const b=Array.from(document.querySelectorAll('button')).find(e=>clean(e.textContent)==='See more');if(!b){complete=true;break;}const before=document.querySelectorAll('[data-listing-row]').length;if(before>=200)break;b.click();const end=Date.now()+6000;while(Date.now()<end&&document.querySelectorAll('[data-listing-row]').length===before){challenge();await new Promise(r=>setTimeout(r,100));}if(document.querySelectorAll('[data-listing-row]').length===before)throw new Error('Native listing expansion did not produce fresh rows.');}const seen=new Set();const all=[];for(const row of document.querySelectorAll('[data-listing-row]')){const a=row.querySelector('h3 a[href]');if(!a)continue;const url=new URL(a.getAttribute('href'),location.origin).href;if(seen.has(url))continue;seen.add(url);const time=row.querySelector('time');all.push({title:clean(a.textContent),url,date:time?.getAttribute('datetime')||clean(time?.textContent)||null,excerpt:null});}if(!all.length)throw new Error('Listing has no parseable article links.');const limit=args.limit??100;return {items:all.slice(0,limit),nextCursor:null,coverage:complete&&all.length<=limit?'complete':'partial',totalLoaded:all.length};}});
action('getPost',{async invoke(args){const u=new URL(args.url);if(u.protocol!=='https:'||u.hostname!=='www.anthropic.com'||!/^\/(research|engineering)\/[^/]+\/?$/.test(u.pathname)||u.search||u.hash)throw new Error('Expected a public www.anthropic.com research or engineering article URL.');const r=await fetch(u.href,{credentials:'omit'});if(r.status===202||r.status===403)throw new Error('Article access blocked or human verification required; do not retry automatically.');if(!r.ok)throw new Error('Article HTTP '+r.status);const d=new DOMParser().parseFromString(await r.text(),'text/html');if(/just a moment|verify you are human/i.test(d.title))throw new Error('Human verification required.');const article=d.querySelector('main article');if(!article)throw new Error('Article content missing; not an empty result.');let meta={};for(const s of d.querySelectorAll('script[type="application/ld+json"]')){try{const m=JSON.parse(s.textContent);if(m['@type']==='Article'){meta=m;break;}}catch{}}const title=clean(article.querySelector('h1')?.textContent||meta.headline);const clone=article.cloneNode(true);for(const e of clone.querySelectorAll('script,style,nav,button,aside,[aria-hidden="true"]'))e.remove();const links=[];const seen=new Set();for(const a of clone.querySelectorAll('a[href]')){try{const link=new URL(a.getAttribute('href'),r.url);if(!/^https?:$/.test(link.protocol))continue;const text=clean(a.textContent);if(text&&!seen.has(link.href)){seen.add(link.href);links.push({title:text,url:link.href});}}catch{}}for(const e of Array.from(clone.querySelectorAll('p,h1,h2,h3,h4,h5,h6,li,pre,blockquote,figcaption,section,header,div,table,tr'))){e.appendChild(d.createTextNode('\n\n'));}const text=clone.textContent.replace(/[ \t]+\n/g,'\n').replace(/\n{3,}/g,'\n\n').trim();if(!title||text.length<300)throw new Error('Article extraction incomplete.');if(text.length>200000)throw new Error('Article exceeds safe text bound; narrow scope required.');return {title,url:r.url,date:meta.datePublished||d.querySelector('time')?.getAttribute('datetime')||null,description:meta.description||d.querySelector('meta[name="description"]')?.content||null,text,links:links.slice(0,200)};}});
});